585 : 
586 :             dxNorm = 0;
587 :             for (int j = 0; j < solvedCols; ++j) {
588 :                 int pj = permutation[j];
589 :                 double s = diag[pj] * lmDir[pj];
590 :                 work3[pj] = s;
591 :                 dxNorm += s * s;
592 :             }
593 :             dxNorm = Math.sqrt(dxNorm);
594 :             double previousFP = fp;
595 :             fp = dxNorm - delta;
596 : 
597 :             // if the function is small enough, accept the current value
598 :             // of lmPar, also test for the exceptional cases where parl is zero
599 :             if ((Math.abs(fp) <= 0.1 * delta) ||
600 :                     ((parl == 0) && (fp <= previousFP) && (previousFP < 0))) {
601 :                 return;
602 :             }
603 : 
604 :             // compute the Newton correction
605 :             for (int j = 0; j < solvedCols; ++j) {
606 :                 int pj = permutation[j];
607 :                 work1[pj] = work3[pj] * diag[pj] / dxNorm;
608 :             }
609 :             for (int j = 0; j < solvedCols; ++j) {
610 :                 int pj = permutation[j];
611 :                 work1[pj] /= work2[j];
612 :                 double tmp = work1[pj];
613 :                 for (int i = j + 1; i < solvedCols; ++i) {
614 :                     work1[permutation[i]] -= jacobian[i][pj] * tmp;
615 :                 }
616 :             }
617 :             sum2 = 0;
618 :             for (int j = 0; j < solvedCols; ++j) {
619 :                 double s = work1[permutation[j]];
620 :                 sum2 += s * s;
621 :             }
622 :             double correction = fp / (delta * sum2);
623 : 
624 :             // depending on the sign of the function, update parl or paru.
625 :             if (fp > 0) {
626 :                 parl = Math.max(parl, lmPar);
627 :             } else if (fp < 0) {
628 :                 paru = Math.min(paru, lmPar);
629 :             }
630 : 
631 :             // compute an improved estimate for lmPar
632 :             lmPar = Math.max(parl, lmPar + correction);
633 : 
634 :         }
635 :     }"

"657 :     private void determineLMDirection(double[] qy, double[] diag,
658 :             double[] lmDiag, double[] work) {
659 : 
660 :         // copy R and Qty to preserve input and initialize s
661 :         //  in particular, save the diagonal elements of R in lmDir
662 :         for (int j = 0; j < solvedCols; ++j) {
663 :             int pj = permutation[j];
664 :             for (int i = j + 1; i < solvedCols; ++i) {
665 :                 jacobian[i][pj] = jacobian[j][permutation[i]];
666 :             }
667 :             lmDir[j] = diagR[pj];
668 :             work[j]  = qy[j];
669 :         }
670 : 
671 :         // eliminate the diagonal matrix d using a Givens rotation
672 :         for (int j = 0; j < solvedCols; ++j) {
673 : 
674 :             // prepare the row of d to be eliminated, locating the
675 :             // diagonal element using p from the Q.R. factorization
676 :             int pj = permutation[j];
677 :             double dpj = diag[pj];
678 :             if (dpj != 0) {
679 :                 Arrays.fill(lmDiag, j + 1, lmDiag.length, 0);
680 :             }
681 :             lmDiag[j] = dpj;
682 : 
683 :             //  the transformations to eliminate the row of d
684 :             // modify only a single element of Qty
685 :             // beyond the first n, which is initially zero.
686 :             double qtbpj = 0;
687 :             for (int k = j; k < solvedCols; ++k) {
688 :                 int pk = permutation[k];
689 : 
690 :                 // determine a Givens rotation which eliminates the
691 :                 // appropriate element in the current row of d
692 :                 if (lmDiag[k] != 0) {
693 : 
694 :                     final double sin;
695 :                     final double cos;
696 :                     double rkk = jacobian[k][pk];
697 :                     if (Math.abs(rkk) < Math.abs(lmDiag[k])) {
698 :                         final double cotan = rkk / lmDiag[k];
699 :                         sin   = 1.0 / Math.sqrt(1.0 + cotan * cotan);
700 :                         cos   = sin * cotan;
701 :                     } else {
702 :                         final double tan = lmDiag[k] / rkk;
703 :                         cos = 1.0 / Math.sqrt(1.0 + tan * tan);
704 :                         sin = cos * tan;
705 :                     }
706 : 
707 :                     // compute the modified diagonal element of R and
708 :                     // the modified element of (Qty,0)
709 :                     jacobian[k][pk] = cos * rkk + sin * lmDiag[k];
710 :                     final double temp = cos * work[k] + sin * qtbpj;
711 :                     qtbpj = -sin * work[k] + cos * qtbpj;
712 :                     work[k] = temp;
713 : 
714 :                     // accumulate the tranformation in the row of s
715 :                     for (int i = k + 1; i < solvedCols; ++i) {
716 :                         double rik = jacobian[i][pk];
717 :                         final double temp2 = cos * rik + sin * lmDiag[i];
718 :                         lmDiag[i] = -sin * rik + cos * lmDiag[i];
719 :                         jacobian[i][pk] = temp2;
720 :                     }
721 : 
722 :                 }
723 :             }
724 : 
725 :             // store the diagonal element of s and restore
726 :             // the corresponding diagonal element of R
727 :             lmDiag[j] = jacobian[j][permutation[j]];
728 :             jacobian[j][permutation[j]] = lmDir[j];
729 : 
730 :         }
731 : 
732 :         // solve the triangular system for z, if the system is
733 :         // singular, then obtain a least squares solution
734 :         int nSing = solvedCols;
735 :         for (int j = 0; j < solvedCols; ++j) {
736 :             if ((lmDiag[j] == 0) && (nSing == solvedCols)) {
737 :                 nSing = j;
738 :             }
739 :             if (nSing < solvedCols) {
740 :                 work[j] = 0;
741 :             }
742 :         }
743 :         if (nSing > 0) {
744 :             for (int j = nSing - 1; j >= 0; --j) {
745 :                 int pj = permutation[j];
746 :                 double sum = 0;
747 :                 for (int i = j + 1; i < nSing; ++i) {
748 :                     sum += jacobian[i][pj] * work[i];
749 :                 }
750 :                 work[j] = (work[j] - sum) / lmDiag[j];
751 :             }
752 :         }
753 : 
754 :         // permute the components of z back to components of lmDir
755 :         for (int j = 0; j < lmDir.length; ++j) {
756 :             lmDir[permutation[j]] = work[j];
757 :         }
758 : 
759 :     }"

"783 :     private void qrDecomposition() throws OptimizationException {
784 : 
785 :         // initializations
786 :         for (int k = 0; k < cols; ++k) {
787 :             permutation[k] = k;
788 :             double norm2 = 0;
789 :             for (int i = 0; i < jacobian.length; ++i) {
790 :                 double akk = jacobian[i][k];
791 :                 norm2 += akk * akk;
792 :             }
793 :             jacNorm[k] = Math.sqrt(norm2);
794 :         }
795 : 
796 :         // transform the matrix column after column
797 :         for (int k = 0; k < cols; ++k) {
798 : 
799 :             // select the column with the greatest norm on active components
800 :             int nextColumn = -1;
801 :             double ak2 = Double.NEGATIVE_INFINITY;
802 :             for (int i = k; i < cols; ++i) {
803 :                 double norm2 = 0;
804 :                 for (int j = k; j < jacobian.length; ++j) {
805 :                     double aki = jacobian[j][permutation[i]];
806 :                     norm2 += aki * aki;
807 :                 }
808 :                 if (Double.isInfinite(norm2) || Double.isNaN(norm2)) {
809 :                     throw new OptimizationException(LocalizedFormats.UNABLE_TO_PERFORM_QR_DECOMPOSITION_ON_JACOBIAN,
810 :                             rows, cols);
811 :                 }
812 :                 if (norm2 > ak2) {
813 :                     nextColumn = i;
814 :                     ak2        = norm2;
815 :                 }
816 :             }
817 :             if (ak2 <= qrRankingThreshold) {
818 :                 rank = k;
819 :                 return;
820 :             }
821 :             int pk                  = permutation[nextColumn];
822 :             permutation[nextColumn] = permutation[k];
823 :             permutation[k]          = pk;
824 : 
825 :             // choose alpha such that Hk.u = alpha ek
826 :             double akk   = jacobian[k][pk];
827 :             double alpha = (akk > 0) ? -Math.sqrt(ak2) : Math.sqrt(ak2);
828 :             double betak = 1.0 / (ak2 - akk * alpha);
829 :             beta[pk]     = betak;
830 : 
831 :             // transform the current column
832 :             diagR[pk]        = alpha;
833 :             jacobian[k][pk] -= alpha;
834 : 
835 :             // transform the remaining columns
836 :             for (int dk = cols - 1 - k; dk > 0; --dk) {
837 :                 double gamma = 0;
838 :                 for (int j = k; j < jacobian.length; ++j) {
839 :                     gamma += jacobian[j][pk] * jacobian[j][permutation[k + dk]];
840 :                 }
841 :                 gamma *= betak;
842 :                 for (int j = k; j < jacobian.length; ++j) {
843 :                     jacobian[j][permutation[k + dk]] -= gamma * jacobian[j][pk];
844 :                 }
845 :             }
846 : 
847 :         }
848 : 
849 :         rank = solvedCols;
850 : 
851 :     }"

"183 :     protected void updateJacobian() throws FunctionEvaluationException {
184 :         ++jacobianEvaluations;
185 :         jacobian = jF.value(point);
186 :         if (jacobian.length != rows) {
187 :             throw new FunctionEvaluationException(point, LocalizedFormats.DIMENSIONS_MISMATCH_SIMPLE,
188 :                                                   jacobian.length, rows);
189 :         }
190 :         for (int i = 0; i < rows; i++) {
191 :             final double[] ji = jacobian[i];
192 :             final double factor = -Math.sqrt(residualsWeights[i]);
193 :             for (int j = 0; j < cols; ++j) {
194 :                 ji[j] *= factor;
195 :             }
196 :         }
