"317 :     public VectorialPointValuePair optimize(final DifferentiableMultivariateVectorialFunction f,
318 :                                             final double[] target, final double[] weights,
319 :                                             final double[] startPoint)
320 :         throws FunctionEvaluationException, OptimizationException, IllegalArgumentException {
321 : 
322 :         if (target.length != weights.length) {
323 :             throw new OptimizationException(LocalizedFormats.DIMENSIONS_MISMATCH_SIMPLE,
324 :                                             target.length, weights.length);
325 :         }
326 : 
327 :         // reset counters
328 :         iterations           = 0;
329 :         objectiveEvaluations = 0;
330 :         jacobianEvaluations  = 0;
331 : 
332 :         // store least squares problem characteristics
333 :         function         = f;
334 :         jF               = f.jacobian();
335 :         targetValues     = target.clone();
336 :         residualsWeights = weights.clone();
337 :         this.point       = startPoint.clone();
338 :         this.residuals   = new double[target.length];
339 : 
340 :         // arrays shared with the other private methods
341 :         rows      = target.length;
342 :         cols      = point.length;
343 :         jacobian  = new double[rows][cols];
344 : 
345 :         cost = Double.POSITIVE_INFINITY;
346 : 
347 :         return doOptimize();
