"488 :     private void determineLMParameter(double[] qy, double delta, double[] diag,
489 :             double[] work1, double[] work2, double[] work3) {
490 : 
491 :         // compute and store in x the gauss-newton direction, if the
492 :         // jacobian is rank-deficient, obtain a least squares solution
493 :         for (int j = 0; j < rank; ++j) {
494 :             lmDir[permutation[j]] = qy[j];
495 :         }
496 :         for (int j = rank; j < cols; ++j) {
497 :             lmDir[permutation[j]] = 0;
498 :         }
499 :         for (int k = rank - 1; k >= 0; --k) {
500 :             int pk = permutation[k];
501 :             double ypk = lmDir[pk] / diagR[pk];
502 :             for (int i = 0; i < k; ++i) {
503 :                 lmDir[permutation[i]] -= ypk * jacobian[i][pk];
504 :             }
505 :             lmDir[pk] = ypk;
506 :         }
507 : 
508 :         // evaluate the function at the origin, and test
509 :         // for acceptance of the Gauss-Newton direction
510 :         double dxNorm = 0;
511 :         for (int j = 0; j < solvedCols; ++j) {
512 :             int pj = permutation[j];
513 :             double s = diag[pj] * lmDir[pj];
514 :             work1[pj] = s;
515 :             dxNorm += s * s;
516 :         }
517 :         dxNorm = Math.sqrt(dxNorm);
518 :         double fp = dxNorm - delta;
519 :         if (fp <= 0.1 * delta) {
520 :             lmPar = 0;
521 :             return;
522 :         }
523 : 
524 :         // if the jacobian is not rank deficient, the Newton step provides
525 :         // a lower bound, parl, for the zero of the function,
526 :         // otherwise set this bound to zero
527 :         double sum2;
528 :         double parl = 0;
529 :         if (rank == solvedCols) {
530 :             for (int j = 0; j < solvedCols; ++j) {
531 :                 int pj = permutation[j];
532 :                 work1[pj] *= diag[pj] / dxNorm;
533 :             }
534 :             sum2 = 0;
535 :             for (int j = 0; j < solvedCols; ++j) {
536 :                 int pj = permutation[j];
537 :                 double sum = 0;
538 :                 for (int i = 0; i < j; ++i) {
539 :                     sum += jacobian[i][pj] * work1[permutation[i]];
540 :                 }
541 :                 double s = (work1[pj] - sum) / diagR[pj];
542 :                 work1[pj] = s;
543 :                 sum2 += s * s;
544 :             }
545 :             parl = fp / (delta * sum2);
546 :         }
547 : 
548 :         // calculate an upper bound, paru, for the zero of the function
549 :         sum2 = 0;
550 :         for (int j = 0; j < solvedCols; ++j) {
551 :             int pj = permutation[j];
552 :             double sum = 0;
553 :             for (int i = 0; i <= j; ++i) {
554 :                 sum += jacobian[i][pj] * qy[i];
555 :             }
556 :             sum /= diag[pj];
557 :             sum2 += sum * sum;
558 :         }
559 :         double gNorm = Math.sqrt(sum2);
560 :         double paru = gNorm / delta;
561 :         if (paru == 0) {
562 :             // 2.2251e-308 is the smallest positive real for IEE754
563 :             paru = 2.2251e-308 / Math.min(delta, 0.1);
564 :         }
565 : 
566 :         // if the input par lies outside of the interval (parl,paru),
567 :         // set par to the closer endpoint
568 :         lmPar = Math.min(paru, Math.max(lmPar, parl));
569 :         if (lmPar == 0) {
570 :             lmPar = gNorm / dxNorm;
571 :         }
572 : 
573 :         for (int countdown = 10; countdown >= 0; --countdown) {
574 : 
575 :             // evaluate the function at the current value of lmPar
576 :             if (lmPar == 0) {
577 :                 lmPar = Math.max(2.2251e-308, 0.001 * paru);
578 :             }
579 :             double sPar = Math.sqrt(lmPar);
580 :             for (int j = 0; j < solvedCols; ++j) {
581 :                 int pj = permutation[j];
582 :                 work1[pj] = sPar * diag[pj];
583 :             }
584 :             determineLMDirection(qy, work1, work2, work3);
585 : 
586 :             dxNorm = 0;
587 :             for (int j = 0; j < solvedCols; ++j) {
588 :                 int pj = permutation[j];
589 :                 double s = diag[pj] * lmDir[pj];
590 :                 work3[pj] = s;
591 :                 dxNorm += s * s;
592 :             }
593 :             dxNorm = Math.sqrt(dxNorm);
594 :             double previousFP = fp;
595 :             fp = dxNorm - delta;
596 : 
597 :             // if the function is small enough, accept the current value
598 :             // of lmPar, also test for the exceptional cases where parl is zero
599 :             if ((Math.abs(fp) <= 0.1 * delta) ||
600 :                     ((parl == 0) && (fp <= previousFP) && (previousFP < 0))) {
601 :                 return;
602 :             }
603 : 
604 :             // compute the Newton correction
605 :             for (int j = 0; j < solvedCols; ++j) {
606 :                 int pj = permutation[j];
607 :                 work1[pj] = work3[pj] * diag[pj] / dxNorm;
608 :             }
609 :             for (int j = 0; j < solvedCols; ++j) {
610 :                 int pj = permutation[j];
611 :                 work1[pj] /= work2[j];
612 :                 double tmp = work1[pj];
613 :                 for (int i = j + 1; i < solvedCols; ++i) {
614 :                     work1[permutation[i]] -= jacobian[i][pj] * tmp;
615 :                 }
616 :             }
617 :             sum2 = 0;
618 :             for (int j = 0; j < solvedCols; ++j) {
619 :                 double s = work1[permutation[j]];
620 :                 sum2 += s * s;
621 :             }
622 :             double correction = fp / (delta * sum2);
623 : 
624 :             // depending on the sign of the function, update parl or paru.
625 :             if (fp > 0) {
626 :                 parl = Math.max(parl, lmPar);
627 :             } else if (fp < 0) {
628 :                 paru = Math.min(paru, lmPar);
629 :             }
630 : 
631 :             // compute an improved estimate for lmPar
632 :             lmPar = Math.max(parl, lmPar + correction);
633 : 
634 :         }
635 :     }"

