"657 :     private void determineLMDirection(double[] qy, double[] diag,
658 :             double[] lmDiag, double[] work) {
659 : 
660 :         // copy R and Qty to preserve input and initialize s
661 :         //  in particular, save the diagonal elements of R in lmDir
662 :         for (int j = 0; j < solvedCols; ++j) {
663 :             int pj = permutation[j];
664 :             for (int i = j + 1; i < solvedCols; ++i) {
665 :                 jacobian[i][pj] = jacobian[j][permutation[i]];
666 :             }
667 :             lmDir[j] = diagR[pj];
668 :             work[j]  = qy[j];
669 :         }
670 : 
671 :         // eliminate the diagonal matrix d using a Givens rotation
672 :         for (int j = 0; j < solvedCols; ++j) {
673 : 
674 :             // prepare the row of d to be eliminated, locating the
675 :             // diagonal element using p from the Q.R. factorization
676 :             int pj = permutation[j];
677 :             double dpj = diag[pj];
678 :             if (dpj != 0) {
679 :                 Arrays.fill(lmDiag, j + 1, lmDiag.length, 0);
680 :             }
681 :             lmDiag[j] = dpj;
682 : 
683 :             //  the transformations to eliminate the row of d
684 :             // modify only a single element of Qty
685 :             // beyond the first n, which is initially zero.
686 :             double qtbpj = 0;
687 :             for (int k = j; k < solvedCols; ++k) {
688 :                 int pk = permutation[k];
689 : 
690 :                 // determine a Givens rotation which eliminates the
691 :                 // appropriate element in the current row of d
692 :                 if (lmDiag[k] != 0) {
693 : 
694 :                     final double sin;
695 :                     final double cos;
696 :                     double rkk = jacobian[k][pk];
697 :                     if (Math.abs(rkk) < Math.abs(lmDiag[k])) {
698 :                         final double cotan = rkk / lmDiag[k];
699 :                         sin   = 1.0 / Math.sqrt(1.0 + cotan * cotan);
700 :                         cos   = sin * cotan;
701 :                     } else {
702 :                         final double tan = lmDiag[k] / rkk;
703 :                         cos = 1.0 / Math.sqrt(1.0 + tan * tan);
704 :                         sin = cos * tan;
705 :                     }
706 : 
707 :                     // compute the modified diagonal element of R and
708 :                     // the modified element of (Qty,0)
709 :                     jacobian[k][pk] = cos * rkk + sin * lmDiag[k];
710 :                     final double temp = cos * work[k] + sin * qtbpj;
711 :                     qtbpj = -sin * work[k] + cos * qtbpj;
712 :                     work[k] = temp;
713 : 
714 :                     // accumulate the tranformation in the row of s
715 :                     for (int i = k + 1; i < solvedCols; ++i) {
716 :                         double rik = jacobian[i][pk];
717 :                         final double temp2 = cos * rik + sin * lmDiag[i];
718 :                         lmDiag[i] = -sin * rik + cos * lmDiag[i];
719 :                         jacobian[i][pk] = temp2;
720 :                     }
721 : 
722 :                 }
723 :             }
724 : 
725 :             // store the diagonal element of s and restore
726 :             // the corresponding diagonal element of R
727 :             lmDiag[j] = jacobian[j][permutation[j]];
728 :             jacobian[j][permutation[j]] = lmDir[j];
729 : 
730 :         }
731 : 
732 :         // solve the triangular system for z, if the system is
733 :         // singular, then obtain a least squares solution
734 :         int nSing = solvedCols;
735 :         for (int j = 0; j < solvedCols; ++j) {
736 :             if ((lmDiag[j] == 0) && (nSing == solvedCols)) {
737 :                 nSing = j;
738 :             }
739 :             if (nSing < solvedCols) {
740 :                 work[j] = 0;
741 :             }
742 :         }
743 :         if (nSing > 0) {
744 :             for (int j = nSing - 1; j >= 0; --j) {
745 :                 int pj = permutation[j];
746 :                 double sum = 0;
747 :                 for (int i = j + 1; i < nSing; ++i) {
748 :                     sum += jacobian[i][pj] * work[i];
749 :                 }
750 :                 work[j] = (work[j] - sum) / lmDiag[j];
751 :             }
752 :         }
753 : 
754 :         // permute the components of z back to components of lmDir
755 :         for (int j = 0; j < lmDir.length; ++j) {
756 :             lmDir[permutation[j]] = work[j];
757 :         }
758 : 
759 :     }"

